pug:
table.row.white-bg.b-system-text-59
    tr
        td.offset-by-one
            table.ten.columns
                tr
                    td.no-padding-bottom
                        p.title.center {{ text_1 }}
                        p.text {{ text_2 }}&nbsp;
                            a(href="{{ href_1 }}", target="_blank") {{ text_3 }}
                            | &nbsp;{{ text_4 }}&nbsp;
                            a(href="{{ href_2 }}", target="_blank") {{ text_5 }}
                            | &nbsp;{{ text_6 }}

styl:
.white-bg.b-system-text-59 {  background:#fff  }
.b-system-text-59 .title {  font-family:Arial!important;color:#f16722;font-size:24px;font-weight:500;line-height:32px;padding-top:30px;padding-bottom:25px  }
@media screen and (max-width:600px) {
  .b-system-text-59 .title {  padding-left:20px!important;padding-right:20px!important  }
}
.b-system-text-59 .text {  font-family:Arial!important;color:#5b6e88;font-size:16px;font-weight:400;line-height:26px;padding-bottom:20px  }
@media screen and (max-width:600px) {
  .b-system-text-59 .text {  padding-left:20px!important;padding-right:20px!important  }
}
.b-system-text-59 .grey-text a, .b-system-text-59 .text a {  color:#0b8bd8;text-decoration:underline  }
.b-system-text-59 .text.bold {  font-weight:700  }
